sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {

  // ---- ① フォームロード中（isLoading=true）の扱い ----
  // 原則：フォームロード時はサーバーへ行かない（重いので）
  // 例外：新規レコードで Requested for に初期値があり、email が空のときだけ 1回取得する
  if (isLoading) {
    tryPopulateOnNewRecordLoad();
    return;
  }

  // ---- ② 通常の onChange（ユーザーが Requested for を変えたとき） ----
  // 空、または変化なしは何もしない
  if (newValue === '' || newValue == oldValue) {
    return;
  }

  // 参照フィールドは newValue が sys_id（これを使うのが確実）
  requestAndSetEmail(newValue);

  // ---- ③ 関数：新規レコードの初期表示時だけ email を埋める ----
  function tryPopulateOnNewRecordLoad() {
    // 新規レコード以外は何もしない
    if (!g_form.isNewRecord || !g_form.isNewRecord()) {
      return;
    }

    // Requested for に値があるのに email が空なら 1回だけ取得
    var reqForSysId = g_form.getValue('u_requested_for');
    var emailNow = g_form.getValue('u_requested_for_email');

    if (reqForSysId && !emailNow) {
      requestAndSetEmail(reqForSysId);
    }
  }

  // ---- ④ 関数：GlideAjax で email を取得してフィールドにセット ----
  function requestAndSetEmail(userSysId) {
    var ga = new GlideAjax('GetEmailAddress');

    // 最初の addParam は sysparm_name（呼び出すサーバーメソッド名）[1](https://snprotips.com/blog/2023/4/28/your-servicenow-acls-are-broken)[2](https://snmastery.com/calling-server-side-code-from-client-script-using-glideajax-in-servicenow/)
    ga.addParam('sysparm_name', 'getEmail');

    // 独自パラメータは sysparm_ で開始（例：sysparm_userID）[1](https://snprotips.com/blog/2023/4/28/your-servicenow-acls-are-broken)[2](https://snmastery.com/calling-server-side-code-from-client-script-using-glideajax-in-servicenow/)
    ga.addParam('sysparm_userID', userSysId);

    // 非同期で answer だけ受け取る（扱いが簡単＆推奨パターン）[2](https://snmastery.com/calling-server-side-code-from-client-script-using-glideajax-in-servicenow/)[1](https://snprotips.com/blog/2023/4/28/your-servicenow-acls-are-broken)
    ga.getXMLAnswer(function(answer) {
      // 必要ならデバッグ用に一時的に残す
      // console.log('[NeedIt Populate Email] answer=', answer);

      g_form.setValue('u_requested_for_email', answer || '');
    });
  }
}
